INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d0a10f1a-d94a-468a-8fed-13521650e943', 'weatherConditions', 'http://w3id.org/glosis/model/codelists/weatherConditionsValueCode', 'Codes for weather conditions.See in Guidelines for Soil Description issued by the FAO: table 2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('627db445-b83f-489e-908b-0e92c5b4a472', 'coatingAbundance', 'http://w3id.org/glosis/model/codelists/coatingAbundanceValueCode', 'Classification of abundance of coatings. See more in Guidelines for Soil Description issued by the FAO: table 64', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d6ce95a9-b748-4845-84e9-fe8482335360', 'weathering', 'http://w3id.org/glosis/model/codelists/weatheringValueCode', 'Classification of weathering of coarse fragments. See more in Guidelines for Soil Description issued by the FAO: table 29', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f7bf91b9-865b-4126-888a-e7e4d689f9f2', 'coatingContrast', 'http://w3id.org/glosis/model/codelists/coatingContrastValueCode', 'Classification of the contrast of coatings. See more in Guidelines for Soil Description issued by the FAO: table 65', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('504817cb-8115-47db-aca2-a13170cc0781', 'coatingForm', 'http://w3id.org/glosis/model/codelists/coatingFormValueCode', 'Classification of the form of coatings. See more in Guidelines for Soil Description issued by the FAO: table 67', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3ad10ad2-d7ba-4f99-b5b1-32eb1d9bde1e', 'biologicalFeatures', 'http://w3id.org/glosis/model/codelists/biologicalFeaturesValueCode', 'Examples of biological features. See more in Guidelines for Soil Description issued by the FAO: table 82', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('05dcae1a-3230-49a9-8994-be7c84dc4a02', 'coatingLocation', 'http://w3id.org/glosis/model/codelists/coatingLocationValueCode', 'Classification of the location of coatings and clay accumulation. See more in Guidelines for Soil Description issued by the FAO: table 68', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ac965fe5-f26f-470e-b19a-ce30f88c519e', 'coatingNature', 'http://w3id.org/glosis/model/codelists/coatingNatureValueCode', 'Classification of the nature of coatings. See more in Guidelines for Soil Description issued by the FAO: table 66', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('6560d880-e7f8-4942-b6e5-95c720d2fd4b', 'consistenceDry', 'http://w3id.org/glosis/model/codelists/consistenceDryValueCode', 'The consistence when dry is determined by breaking an air-dried mass of soil between thumb and forefinger or in the hand. See more in the guidelines for Soil Description issued by the FAO: table 53', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('02b78802-dd53-4c9f-a6df-31adc2a81f6e', 'consistenceMoist', 'http://w3id.org/glosis/model/codelists/consistenceMoistValueCode', 'Guidelines for Soil Description issued by the FAO: table 54;Consistence when moist is determined by attempting to crush a mass of moist or slightly moist soil material. See more in Guidelines for Soil Description issued by the FAO: table 54', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('165dc060-e2d7-4b46-b7d4-796e66ba4e3c', 'contrast', 'http://w3id.org/glosis/model/codelists/contrastValueCode', 'The colour contrast between mottles and soil matrix. See more in Guidelines for Soil Description issued by the FAO: table 34', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5ca22b00-f3b7-4c61-978c-4ca125b59a9b', 'cracksDepth', 'http://w3id.org/glosis/model/codelists/cracksDepthValueCode', 'List of suggested classes of surface cracks in shrink–swell clay-rich soils after they dry out. See more in guidelines for Soil Description issued by the FAO: table 21,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('35aa0ef0-ca64-4115-980d-989865da8777', 'cracksDistance', 'http://w3id.org/glosis/model/codelists/cracksDistanceValueCode', 'Classification of the surface cracks based on distance between the cracks measured in meters. See more in Guidelines for Soil Description issued by the FAO: table 21,3', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4888bca3-64d5-430a-9b23-aee441a77660', 'cracksWidth', 'http://w3id.org/glosis/model/codelists/cracksWidthValueCode', 'Classification of surface cracks based on the width. See more in Guidelines for Soil Description issued by the FAO: table 21,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('dc62f0cc-ef7b-4284-87d3-38430154c422', 'cropClass', 'http://w3id.org/glosis/model/codelists/cropClassValueCode', 'Examples for the most common crops with their recommended codes. See more in guidelines for Soil Description issued by the FAO: table 9', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3413b056-fef2-4e27-9eaa-772c6b8b21d6', 'bleachedSand', 'http://w3id.org/glosis/model/codelists/bleachedSandValueCode', 'Classification of bleached sand characteristics based on the percentage of surface covered. See more in Guidelines for Soil Description issued by the FAO: table 23', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ff123064-31c0-45e9-a504-3f59a3e24991', 'erosionActivityPeriod', 'http://w3id.org/glosis/model/codelists/erosionActivityPeriodValueCode', 'The period of activity of accelerated erosion or deposition is described using the recommended classes. See more in Guidelines for Soil Description issued by the FAO: table 19', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e9df9ce3-5925-4d27-a29e-fffe2fbfc43a', 'erosionAreaAffected', 'http://w3id.org/glosis/model/codelists/erosionAreaAffectedValueCode', 'Classification of total area affected by erosion and deposition. See more in Guidelines for Soil Description issued by the FAO: table 17', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4b0309c2-d7b8-4f0f-9b72-65ba285f2555', 'erosionCategory', 'http://w3id.org/glosis/model/codelists/erosionCategoryValueCode', 'Erosion can be classified as water or wind erosion and include off-site effects such as deposition; a third major category is mass movements (landslides and related phenomena). See more in Guidelines for Soil Description issued by the FAO: table 16', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('238d4717-ca4c-455d-92d6-21cc870aedee', 'erosionDegree', 'http://w3id.org/glosis/model/codelists/erosionDegreeValueCode', 'Classification of erosion, by degree. See more in guidelines for Soil Description issued by the FAO: table 18', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a127e308-7fe5-4f09-815d-63eb1c6cef88', 'erosionTotalAreaAffected', 'http://w3id.org/glosis/model/codelists/erosionTotalAreaAffectedValueCode', 'The total area affected by erosion and deposition is estimated following the classes defined by SOTER (FAO, 1995). See more in the Guidelines for Soil Description issued by the FAO: table 17', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('9f6f76fe-773d-4451-a53e-b59593b31295', 'boundaryClassification', 'http://w3id.org/glosis/model/codelists/boundaryClassificationValueCode', 'The boundary between mottle and matrix is described as the thickness of the zone within which the colour transition can be located without being in either the mottle or matrix. See more in guidelines for Soil Description issued by the FAO: table 35', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('15ab8cac-5ae8-4528-b4b4-e1baa7f83187', 'fragmentCover', 'http://w3id.org/glosis/model/codelists/fragmentCoverValueCode', 'Coarse surface fragments, including those partially exposed, should be described in terms of percentage of surface coverage and of size of the fragments. See more in Guidelines for Soil Description issued by the FAO: table 15,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5a3c8cd1-73cc-4701-b96c-59e680d7cb1a', 'fragmentsClass', 'http://w3id.org/glosis/model/codelists/fragmentsClassValueCode', 'Horizon properties encountered in a global data compilation programme. See more in ISRIC Report 2019/01: Tier 1 and Tier 2 data in the context of the federated Global Soil Information System. Appendix 3', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('71af80ac-8274-42c6-a960-bab2a203cf3b', 'fragmentsSize', 'http://w3id.org/glosis/model/codelists/fragmentsSizeValueCode', 'Classes of occurrence of coarse surface fragments are correlated with the ones for rock outcrop. See more in guidelines for Soil Description issued by the FAO: table 15,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('10903413-9e20-4b5c-8afe-8e8e0300468f', 'gypsumContent', 'http://w3id.org/glosis/model/codelists/gypsumContentValueCode', 'Where more readily soluble salts are absent, gypsum can be estimated in the field by measurements of electrical conductivity. More in the guidelines for Soil Description issued by the FAO: table 40', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('63af6715-ce4f-4830-a0aa-9c7666086d90', 'gypsumForms', 'http://w3id.org/glosis/model/codelists/gypsumFormsValueCode', 'The forms of secondary gypsum in soils are diverse and are considered to be informative for diagnostics of soil genesis. See more information in the Guidelines for Soil Description issued by the FAO: table 41', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('cb1379e6-651d-4da8-b500-ed968de95d78', 'boundaryDistinctness', 'http://w3id.org/glosis/model/codelists/boundaryDistinctnessValueCode', 'The distinctness of the boundary refers to the thickness of the zone in which the horizon boundary can be located without being in one of the adjacent horizons. See more in the Guidelines for Soil Description issued by the FAO: table 24.1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('0d8d668a-6036-4858-9c92-564eccac7019', 'humanInfluenceClass', 'http://w3id.org/glosis/model/codelists/humanInfluenceClassValueCode', 'This item refers to any evidence of human activity that is likely to have affected the landscape or the physical and chemical properties of the soil. See more in the Guidelines for Soil Description issued by the FAO: table 10', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4072bfd6-547d-4cf1-9a1d-f3f9e1a9031b', 'landUseClass', 'http://w3id.org/glosis/model/codelists/landUseClassValueCode', 'Land use applies to the current use of the land, whether agricultural or nonagricultural, in which the soil is located. See more in the guidelines for Soil Description issued by the FAO: table 8', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('dde3a4b4-95ae-437d-83de-01e51f933af8', 'boundaryTopography', 'http://w3id.org/glosis/model/codelists/boundaryTopographyValueCode', 'Classification of horizon boundaries by topography. See more in Guidelines for Soil Description issued by the FAO: table 24,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a0df5bce-34de-443d-bd74-0923262eeff8', 'landformComplex', 'http://w3id.org/glosis/model/codelists/landformComplexValueCode', 'Subdivisions for complex landforms. See more in Guidelines for Soil Description issued by the FAO: table 5', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3a6537c7-7866-4ce5-a98a-ea2c95f93f7f', 'bulkDensityMineral', 'http://w3id.org/glosis/model/codelists/bulkDensityMineralValueCode', 'Field determinations of bulk density may be obtained by estimating the force required to push a knife into a soil horizon exposed at a field moist pit wall. See more in Guidelines for Soil Description issued by the FAO: table 58', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('579fb467-0153-4f3f-9e3c-87b1cc9612f6', 'lithology', 'http://w3id.org/glosis/model/codelists/lithologyValueCode', 'In order to be able to work in smaller scales, some additional natural and anthropogenic parent materials are used for the identification of rocks in the field, the keys to the most important rock types are provided in the hierarchical SOTER list. See more in the guidelines for Soil Description issued by the FAO: table 12', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ecab7a7c-16dc-49e3-8a69-4387c7cde3f0', 'bulkDensityPeat', 'http://w3id.org/glosis/model/codelists/bulkDensityPeatValueCode', 'Bulk density and volume of solids of organic soils can be estimated after the decomposition stage or the extent of peat drainage. See more in guidelines for Soil Description issued by the FAO: table 59,3', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4b9886ab-b838-4a4f-9715-31b68a57184b', 'majorLandForm', 'http://w3id.org/glosis/model/codelists/majorLandFormValueCode', 'Hierarchy of major landforms. See more in Guidelines for Soil Description issued by the FAO: table 4', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3ae52955-c2f4-45ec-b628-32b9a85558d4', 'mineralConcColour', 'http://w3id.org/glosis/model/codelists/mineralConcColourValueCode', 'The general colour names are usually sufficient to describe the colour of the nodules (similar to mottles) or of artefacts. See more in Guidelines for Soil Description issued by the FAO: table 78', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('9fcd867c-fc4d-427c-beca-5112b030f256', 'carbonatesContent', 'http://w3id.org/glosis/model/codelists/carbonatesContentValueCode', 'Classes for the reaction of carbonates in the soil matrix. See more in Guidelines for Soil Description issued by the FAO: table 38', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ece0eae1-f849-4ecf-b466-67834e554831', 'mineralConcHardness', 'http://w3id.org/glosis/model/codelists/mineralConcHardnessValueCode', 'Classification of the hardness of mineral concentrations. More in the Guidelines for Soil Description issued by the FAO: table 76', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('337fcb51-ba33-4dc4-9ad1-7772378ce0bd', 'mineralConcKind', 'http://w3id.org/glosis/model/codelists/mineralConcKindValueCode', 'Classification of the kinds of mineral concentrations. See more in guidelines for Soil Description issued by the FAO: table 74', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a3d7b957-3adf-423f-ba25-ac5070ffd4a8', 'mineralConcNature', 'http://w3id.org/glosis/model/codelists/mineralConcNatureValueCode', 'Mineral concentrations are described according to the composition or impregnating substance.See more in Guidelines for Soil Description issued by the FAO: 77', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('56589846-0f0b-4c86-913d-b8795c6b30ac', 'mineralConcShape', 'http://w3id.org/glosis/model/codelists/mineralConcShapeValueCode', 'Classification of the size and shape of mineral concentrations. See more in Guidelines for Soil Description issued by the FAO: table 75,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('19231507-3d71-4cb0-b4fd-c2646d947ff8', 'mineralConcSize', 'http://w3id.org/glosis/model/codelists/mineralConcSizeValueCode', 'Classification of mineral concentrations based on size. See more in Guidelines for Soil Description issued by the FAO: table 75,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f31153c3-375f-44ef-bfba-2e461350c198', 'mineralConcVolume', 'http://w3id.org/glosis/model/codelists/mineralConcVolumeValueCode', 'The mineral concentrations are described according to their abundance, kind, size, shape, hardness, nature and colour. See more onGuidelines for Soil Description issued by the FAO: table 73', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7a5ae2f2-47bf-417a-ac93-bc85d46049cf', 'mineralFragments', 'http://w3id.org/glosis/model/codelists/mineralFragmentsValueCode', 'Codes for primary mineral fragments. See more in Guidelines for Soil Description issued by the FAO: table 30', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('64cc7436-5c58-45f5-9577-47e6cba8c9da', 'mottlesAbundance', 'http://w3id.org/glosis/model/codelists/mottlesAbundanceValueCode', 'The abundance of mottles is described in terms of classes indicating the percentage of the exposed surface that the mottles occupy. See more in the Guidelines for Soil Description issued by the FAO: table 32', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e1550663-3b05-4549-b4ce-5d22e6a8af74', 'carbonatesForms', 'http://w3id.org/glosis/model/codelists/carbonatesFormsValueCode', 'The forms of secondary carbonates in soils are diverse and are considered to be informative for diagnostics of soil genesis. See more in guidelines for Soil Description issued by the FAO: table 39', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a2c73d17-795e-419d-876c-c61e55351613', 'mottlesSize', 'http://w3id.org/glosis/model/codelists/mottlesSizeValueCode', 'The individual classes of the mottle nodules according to their diameter size. See more in the guidelines for Soil Description issued by the FAO: table 33', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ca88d2ef-255a-4a78-9ec4-6bc05e261b7e', 'peatDecompostion', 'http://w3id.org/glosis/model/codelists/peatDecompostionValueCode', 'In most organic layers of rocks the determination of the texture class is done by estimating of the degree of decomposition and humification of the organic material.See more in Guidelines for Soil Description issued by the FAO: table 31', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('41cb0388-aa0c-481c-a32e-9d1ec8121e6e', 'peatDrainage', 'http://w3id.org/glosis/model/codelists/peatDrainageValueCode', 'Bulk density and volume of solids of organic soils may be estimated after the decomposition stage or the extent of peat drainage. More information is in the guidelines for Soil Description issued by the FAO: table 59,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('1f6f81e9-d184-415d-b64c-c25b09d16d97', 'peatVolume', 'http://w3id.org/glosis/model/codelists/peatVolumeValueCode', 'Field estimation of volume of solids and bulk density of peat soils. See more in Guidelines for Soil Description issued by the FAO: table 59,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3b0b162a-6615-46b4-bf47-fe99c40b3d64', 'cementationContinuity', 'http://w3id.org/glosis/model/codelists/cementationContinuityValueCode', 'The occurrence of cementation or compaction in pans or otherwise is described according to its nature, continuity, structure, agent and degree. See more in the guidelines for Soil Description issued by the FAO: table 69', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('548f769f-6254-4576-959a-c95d6227edb3', 'biologicalAbundance', 'http://w3id.org/glosis/model/codelists/biologicalAbundanceValueCode', 'Classification of the abundance of biological activity. See more in Guidelines for Soil Description issued by the FAO: table 81', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b73016ca-9fa0-42ce-827c-49ad07fdca2b', 'cementationDegree', 'http://w3id.org/glosis/model/codelists/cementationDegreeValueCode', 'The classification of the degree of cementation/compaction. See more in Guidelines for Soil Description issued by the FAO: table 72', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e6a9dfc8-8b47-4192-9f1d-8b9a0185a223', 'physiography', 'http://w3id.org/glosis/model/codelists/physiographyValueCode', 'The relative position of the site within the land should be indicated. The position affects the hydrological conditions of the site. See more in the Guidelines for Soil Description issued by the FAO: figure 2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('1efa3a27-5a9c-43e4-8a3a-9cc36e56a05d', 'plasticity', 'http://w3id.org/glosis/model/codelists/plasticityValueCode', 'Plasticity is the ability of soil material to change shape continuously under the influence of an applied stress and to retain the compressed shape on removal of stress. See more in Guidelines for Soil Description issued by the FAO: Guidelines for Soil Description issued by the FAO: table 56', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a043b2c2-ce9d-4d9c-81a1-efe6d00c9bb5', 'poresAbundance', 'http://w3id.org/glosis/model/codelists/poresAbundanceValueCode', 'Classification of abundance of pores. See more in Guidelines for Soil Description issued by the FAO: table 63', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f71060d3-12fc-4cd3-8747-ef5f2e7c3fff', 'porosityClass', 'http://w3id.org/glosis/model/codelists/porosityClassValueCode', 'The porosity is an indication of the total volume of voids discernible with a ×10 hand-lens measured by area and recorded as the percentage of the surface occupied by pores. See more in guidelines for Soil Description issued by the FAO: table 60', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('9db8169c-05e9-4b3e-90b8-4386d34681d3', 'profileDescriptionStatus', 'http://w3id.org/glosis/model/codelists/profileDescriptionStatusValueCode', 'Soil profile description status. See more in Guidelines for Soil Description issued by the FAO: table 1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('22a71ab2-9383-4d1c-b237-12af30405e56', 'rockAbundance', 'http://w3id.org/glosis/model/codelists/rockAbundanceValueCode', 'Abundance of rock fragments and artefacts, by volume. See more in Guidelines for Soil Description issued by the FAO: table 26', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('dc1ad36e-930f-4cb3-aa7a-db895113a126', 'rockOutcropsCover', 'http://w3id.org/glosis/model/codelists/rockOutcropsCoverValueCode', 'Recommended classes of percentage of surface cover and of average distance between rock outcrops. See more in Guidelines for Soil Description issued by the FAO: table 14,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c428a347-3902-4960-8233-bab471833805', 'rockOutcropsDistance', 'http://w3id.org/glosis/model/codelists/rockOutcropsDistanceValueCode', 'Recommended classes of percentage of surface cover and of average distance between rock outcrops. See more in Guidelines for Soil Description issued by the FAO: table 14,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d7b2a2dd-42c5-42d4-b611-3413097a0199', 'rockShape', 'http://w3id.org/glosis/model/codelists/rockShapeValueCode', 'The general shape or roundness of rock fragments. See more on Guidelines for Soil Description issued by the FAO: table 28', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5e1bf331-8652-46f3-8d04-5a19d50bdcc0', 'rockSize', 'http://w3id.org/glosis/model/codelists/rockSizeValueCode', 'Classification for rock fragments and artefacts influences the nutrient status, water movement, use and management of the soil. See more in guidelines for Soil Description issued by the FAO: table 27', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('30b93785-2f67-4772-8b09-61a02191967a', 'cementationFabric', 'http://w3id.org/glosis/model/codelists/cementationFabricValueCode', 'Classification of the fabric of the cemented/compacted layer. See more in Guidelines for Soil Description issued by the FAO: table 70', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d1b1458e-0214-4029-9146-8c65bdf2ff0c', 'rootsAbundance', 'http://w3id.org/glosis/model/codelists/rootsAbundanceValueCode', 'classification of the abundance of roots.. See more in Guidelines for Soil Description issued by the FAO: table 80', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('41d9b473-8495-4e1c-b55e-2b41de565ea7', 'saltContent', 'http://w3id.org/glosis/model/codelists/saltContentValueCode', 'Classification of salt content of soil. See more in Guidelines for Soil Description issued by the FAO: table 42', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('1ae54454-9160-4248-af0f-158a02af057e', 'saltCover', 'http://w3id.org/glosis/model/codelists/saltCoverValueCode', 'The occurrence of salt at the surface may be described in terms of cover, appearance and type of salt. See more in the guidelines for Soil Description issued by the FAO: table 22,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('23f9b107-6248-438d-a9ab-0d1637727b6c', 'saltThickness', 'http://w3id.org/glosis/model/codelists/saltThicknessValueCode', 'The occurrence of salt at the surface may be described in terms of cover, appearance and type of salt. See more in the Guidelines for Soil Description issued by the FAO: table 22,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7c81b713-250b-4475-afb0-23958c54f52a', 'cementationNature', 'http://w3id.org/glosis/model/codelists/cementationNatureValueCode', 'Classification of the nature of cementation/compaction. See more in Guidelines for Soil Description issued by the FAO: table 71', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b7587f36-55b5-42ee-b76d-668a24bfdc41', 'sandyTexture', 'http://w3id.org/glosis/model/codelists/sandyTextureValueCode', 'Relation of constituents of fine earth by size, defining textural classes and sand subclasses. See more in Guidelines for Soil Description issued by the FAO: figure 4,3', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('6823eefa-ed63-4348-92e9-052ed5f29d8c', 'sealingConsistence', 'http://w3id.org/glosis/model/codelists/sealingConsistenceValueCode', 'Classification of the attributes of surface sealing based on consistency. See more in Guidelines for Soil Description issued by the FAO: table 20,2', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d77da748-b058-45da-9f77-8a772d739b51', 'sealingThickness', 'http://w3id.org/glosis/model/codelists/sealingThicknessValueCode', 'Surface sealing is used to describe crusts that develop at the soil surface after the topsoil dries out. See more in Guidelines for Soil Description issued by the FAO: 20,1', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('cf9e5069-7d46-4938-affa-de8b8e9fcca7', 'slopeForm', 'http://w3id.org/glosis/model/codelists/slopeFormValueCode', 'The slope form refers to the general shape of the slope in both the vertical and horizontal directions. See more in Guidelines for Soil Description issued by the FAO: table 6', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('32f83c56-58c6-4c36-a85d-d9a453877058', 'slopeGradientClass', 'http://w3id.org/glosis/model/codelists/slopeGradientClassValueCode', 'Slope gradient classes measured on the percentage of slope. See more in Guidelines for Soil Description issued by the FAO: table 7', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('8a850c34-6aa0-480f-a3f4-f7adc7114cad', 'slopePathways', 'http://w3id.org/glosis/model/codelists/slopePathwaysValueCode', 'The slope form refers to the general shape of the slope in both the vertical and horizontal directions. See more in guidelines for Soil Description issued by the FAO: figure 3', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('228b7b7b-df51-4d25-bb07-fcd8543827f7', 'stickiness', 'http://w3id.org/glosis/model/codelists/stickinessValueCode', 'Stickiness is the quality of adhesion of the soil material to other objects determined by noting the adherence of soil material when it is pressed between thumb and finger. See more in the Guidelines for Soil Description issued by the FAO: table 55', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5a46dd1b-9e8d-4138-86aa-410289cdfe57', 'structureGrade', 'http://w3id.org/glosis/model/codelists/structureGradeValueCode', 'Guidelines for Soil Description issued by the FAO: table 47; Classification of structure of pedal soil materials. See more in Guidelines for Soil Description issued by the FAO: table 47', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c40a1e8a-9aa1-4f97-be5b-f053ce8a2890', 'structureSize', 'http://w3id.org/glosis/model/codelists/structureSizeValueCode', 'Size classes for soil structure types. See more in guidelines for Soil Description issued by the FAO: table 50', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('953a3ce0-f992-43a9-b746-aeb3b559310c', 'surfaceAge', 'http://w3id.org/glosis/model/codelists/surfaceAgeValueCode', 'The age of the landscape is important information from which the possible duration of the occurrence of soil formation processes can be derived. See more in guidelines for Soil Description issued by the FAO: table 13', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('8e18bd14-f491-43b9-b866-afafabf7ae5d', 'vegetationClass', 'http://w3id.org/glosis/model/codelists/vegetationClassValueCode', 'Classification of vegetation.See more in Guidelines for Soil Description issued by the FAO: table 11', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('cef6d110-c603-4280-ae7d-52c013e4b292', 'voidsClassification', 'http://w3id.org/glosis/model/codelists/voidsClassificationValueCode', 'Voids include all empty spaces in the soil. They are related to the arrangement of the primary soil constituents, rooting patterns, burrowing of animals or any other soil-forming processes, such as cracking, translocation and leaching. See more in Guidelines for Soil Description issued by the FAO: table 61', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c8cc9fff-f4eb-470d-a1fc-38c0793ad77e', 'voidsDiameter', 'http://w3id.org/glosis/model/codelists/voidsDiameterValueCode', 'Voids include all empty spaces in the soil. They are related to the arrangement of the primary soil constituents, rooting patterns, burrowing of animals or any other soil-forming processes, such as cracking, translocation and leaching. See more in Guidelines for Soil Description issued by the FAO: table 62', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('fa690496-bbd4-4fb9-aa85-6edb70b78e5e', 'Aciexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Aciexc', 'Exchangeable acidity represents the amount of hydrogen (H⁺) and aluminum (Al³⁺) ions adsorbed onto soil particles that can be exchanged with the soil solution. It is a key factor in determining soil liming requirements and improving nutrient availability in acidic soils. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('aa6e259d-e2b9-4fc8-8fa2-9f77477c2433', 'Aciext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Aciext', 'Extractable acidity measures the active acidity in soil, including hydrogen ions in the soil solution and weakly bound to colloids. It is critical for assessing lime requirements and addressing soil pH imbalances to improve plant growth. Source: Soil Chemistry by Bohn et al.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c8fda617-0615-4901-bc7b-ae99caaf2820', 'Alu', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Alu', 'Sum of the oxalate-extractable aluminium concentration plus half the oxalate-extractable iron concentration', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c82f2de7-287c-411b-9486-2b74adb2e72c', 'Aludit', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Aludit', '''Free'' aluminium content extracted from amorphous compounds (weathering products) as well as crystaline, primary aluminium compounds (parent material) in the soil.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('790f3270-ac45-4e5c-a675-f2f43c3df547', 'Aluexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Aluexc', 'Aluminium ions bound to exchange surfaces in the soil such as clay minerals and organic matter that can be released to the soil solution upon exchange', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('dbc9b971-620e-45a6-8b42-8184bc505bd0', 'Aluext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Aluext', 'Aluminium bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a7eec5f0-15d2-494d-8fc5-e6e1d559081a', 'Aluoxa', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Aluoxa', '''Active'' aluminium content extracted from amorphous aluminium compounds that are the products of the weathering of primary soil particles', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('fde6a5f3-0e7f-4841-86b3-a2aaf330a1b6', 'Alupyr', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Alupyr', 'Aluminium in soil that is organically bound in organo-metal complexes', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5eadcbe9-36c8-465c-98d3-21135574b384', 'Alusat', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Alusat', 'Measure to describe the relative abundance of alumium in the soil. It is the percentage of the CEC occupied by aluminium', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f5ba4320-09c9-4cb5-8a05-742158e47a7b', 'Alutot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Alutot', 'Total concentration of aluminium in the soil, including both soluble and insoluble forms, typically measured after complete digestion of the soil sample.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e95103ee-f9b2-4c8d-9577-9591bc568017', 'Avavol', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Avavol', 'Available water capacity (AWC) measures the volume of water soil can retain between field capacity and the permanent wilting point. It represents the water accessible to plants for uptake. High AWC supports better plant growth, while low AWC may necessitate irrigation. Source: USDA NRCS.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('bf771dfa-b719-4460-9a80-cb4a026ebf64', 'Bascal', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Bascal', 'Base saturation represents the percentage of the soil''s cation exchange capacity (CEC) occupied by basic cations such as calcium (Ca²⁺), magnesium (Mg²⁺), potassium (K⁺), and sodium (Na⁺). Higher base saturation typically correlates with higher fertility and a greater ability to supply essential nutrients to plants. This parameter also influences soil pH buffering capacity. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f9fedb81-83cd-4adf-9bb5-e5e614a01a24', 'Basexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Basexc', 'Exchangeable bases refer to the cations (e.g., calcium, magnesium, potassium, and sodium) adsorbed onto soil colloids, which can readily exchange with soil solution ions. These cations are crucial for maintaining soil fertility, affecting nutrient availability and pH buffering capacity. High exchangeable base levels indicate fertile soil conducive to plant growth. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('63285183-74f1-49e2-8f12-cce6870f9737', 'Bassum', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Bassum', 'Base saturation calculated as the sum of cations represents the proportion of the cation exchange capacity (CEC) occupied by essential base cations like calcium, magnesium, potassium, and sodium. It provides insight into the soil''s fertility status and its ability to resist acidification. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('19f75870-1382-4e53-b348-28d4b76d5283', 'Borext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Borext', 'Boron bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c4d46d2f-db48-4cb1-8536-1dc477d89ee5', 'Bortot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Bortot', 'Total boron includes all boron forms in soil, crucial for plant cell wall formation and reproductive processes. Deficiency can impair growth, while toxicity is a risk in arid soils or with excessive irrigation. Source: Havlin et al. (2014).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('45706630-b0a0-4d03-b05b-9b0bb036f737', 'Brod', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Brod', 'Bromide bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('91d7cd70-c294-45e9-a729-569ec84f1a23', 'Brot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Brot', 'Bromite (BrO₂⁻) is a rare intermediate oxidation state of bromine, generally not prevalent in natural soils. It may arise under specific chemical or environmental conditions and is of limited importance in typical soil science contexts. Source: Environmental Chemistry Textbooks.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('98861b36-7670-4c00-a886-3f501ca294df', 'BulDfine', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-BulDfine', 'This parameter measures the bulk density of the soil fraction smaller than 2 mm (excluding rocks and coarse fragments). It is used to assess the physical properties of soil related to root growth, water movement, and compaction. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('bfa9f4e4-04cf-436b-b942-3f3e4850a11b', 'BulDwhole', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-BulDwhole', 'Bulk density measures the mass of soil per unit volume, including both solids and pore spaces. It is a critical parameter for assessing soil compaction, porosity, and water infiltration capacity. High bulk density often indicates poor aeration and root penetration, while low values are associated with high organic matter content and good structure. Source: USDA NRCS.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ab6ebe5f-be2e-48b2-ba21-c77febd9f072', 'CEC', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-CEC', 'CEC measures the soil’s ability to hold and exchange positively charged ions (cations). It is a critical indicator of soil fertility, as higher CEC values imply greater capacity to retain essential nutrients like calcium, magnesium, and potassium. Clayey and organic-rich soils typically exhibit higher CEC. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ee5da973-b6b1-4bd7-b0bc-d3b12b5b44be', 'CaN', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-CaN', 'The C/N ratio represents the proportion of carbon to nitrogen in organic matter. It influences decomposition rates and nutrient availability. A lower C/N ratio promotes rapid organic matter breakdown and nitrogen release, while a high ratio may lead to nitrogen immobilization, affecting plant growth. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ea67fefe-5328-4e3e-a3cd-e73192682a9c', 'Cad', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Cad', 'Cadmium is a heavy metal present in trace amounts in soils, often introduced through industrial pollution or phosphate fertilizers. It is toxic to plants, animals, and humans even at low concentrations. Monitoring cadmium levels is crucial to ensure soil safety and reduce contamination risks in the food chain. Source: Sparks, D.L. (2003).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('8bff64ab-5bf2-46ea-90d1-a3ed0e3501b1', 'Calexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Calexc', 'Calcium bound to exchange surfaces in the soil such as clay minerals and organic matter that can be released to the soil solution upon exchange', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7e2579dd-b674-405b-bfde-d3b67868d851', 'Calext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Calext', 'Calcium bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('9120a40f-8800-4e7a-86b1-6a5b1d416fd8', 'Calfra', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Calfra', 'This term quantifies the fraction of calcium carbonate (CaCO₃) in soil, indicating its lime content. Calcium carbonate acts as a pH buffer, neutralizing soil acidity and enhancing nutrient availability. High levels improve soil structure and aggregate stability, making it especially valuable for acidic soils. Source: FAO Soil Bulletin.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('cc0ea06b-e954-45f5-89e9-65fbf5d840e8', 'Calsol', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Calsol', 'Soluble Calcium cations accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('43c34161-f4a3-495f-85cb-68a9bfaeb4c1', 'Caltot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Caltot', 'Total calcium in soil includes all forms, from exchangeable calcium to calcium in minerals. It is essential for plant cell wall structure, enzyme activation, and soil aggregation. Calcium levels influence soil pH and nutrient availability. Source: Havlin et al. (2014).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c44eec99-4d0d-45b6-badf-7bfb11f1c5e9', 'Car', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Car', 'Soluble carbonates contribute to soil alkalinity and act as a pH buffer. They play a role in nutrient availability, particularly in arid and semi-arid regions, but excessive carbonates can immobilize certain nutrients like phosphorus and iron. Source: Soil Chemistry by Bohn et al.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3b24e0df-34d3-4db4-921b-cb69b86320cb', 'Carful', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Carful', 'Fulvic acid carbon is the most soluble and bioavailable fraction of soil organic matter. It plays a significant role in improving nutrient uptake, soil structure, and microbial activity, thereby enhancing soil productivity. Source: Stevenson, F.J. (1994).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a2bed510-4953-437e-910b-e8917a704e08', 'Carhum', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Carhum', 'Humic acid carbon is part of the soil organic matter, forming during the decomposition of plant and animal residues. It enhances nutrient retention, soil structure, and water-holding capacity, playing a vital role in maintaining soil fertility and resilience. Source: Stevenson, F.J. (1994). Humus Chemistry: Genesis, Composition, Reactions.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('aba52acc-5ba4-4940-9f6d-22a5b816adbc', 'Carinorg', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Carinorg', 'Inorganic carbon in soil primarily consists of carbonates like calcium carbonate and magnesium carbonate. It contributes to soil pH buffering and is a significant feature of arid and calcareous soils. Excess inorganic carbon can immobilize certain nutrients, requiring careful management in agricultural systems. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('09b9f784-0bee-49ee-aaae-9320e0e258f6', 'Carorg', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Carorg', 'Organic carbon refers to the carbon component of soil organic matter, derived from decomposed plant and microbial residues. It serves as a key energy source for soil microbes and influences nutrient cycling, soil structure, and water retention. Organic carbon is a primary indicator of soil fertility and health. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('6d3f7122-ada8-4574-b172-85aad6971e8d', 'Carpyr', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Carpyr', 'Carbon in soil that is organically bound in organo-metal complexes', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a0ae637a-e938-46e1-8b89-9d5189ff9eba', 'Cartoh', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Cartoh', 'Total humic carbon represents the stable fraction of soil organic matter derived from humified materials. It improves soil structure, nutrient retention, and water-holding capacity, making it critical for long-term soil health and productivity. Source: Stevenson, F.J. (1994).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('6022fde8-d281-4d85-92ae-2279f6415245', 'Cartot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Cartot', 'Total carbon in soil includes both organic carbon (from plant and microbial residues) and inorganic carbon (primarily carbonates). It is a fundamental component of soil organic matter, influencing soil fertility, structure, and water retention. High carbon levels are associated with better soil health and productivity. Source: USDA NRCS.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7976704c-e21d-4655-a1fa-a0d831905ad8', 'Ccetot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Ccetot', 'The total calcium carbonate equivalent measures the full capacity of soil to neutralize acidity, considering all forms of carbonate and bicarbonate minerals. It is essential for managing soil pH and nutrient availability in acidic soils. Source: FAO Soil Bulletin.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4126df87-3fbd-4e93-8fe4-2bd96314a546', 'Chl', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Chl', 'Soluble Chloride anions accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('0879b015-8a22-44f7-9efe-bd6291ffb0d2', 'Copext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Copext', 'Copper bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('01be5661-8e3f-4c69-866e-531442f9ac70', 'Coptot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Coptot', 'Total copper comprises all soil copper, including bound and free forms. Copper is vital for plant enzyme activation and metabolic processes. Deficiencies can lead to reduced growth and yields, while excess copper may inhibit root development. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('71d446b5-8f17-4c48-825f-4feab5d9c8e0', 'ECEC', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-ECEC', 'ECEC is the sum of exchangeable cations in soil at its natural pH. It provides a measure of the soil’s fertility under acidic conditions, as it considers both base cations and exchangeable aluminum. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('01a9e264-60c9-4e0b-b6ec-07d90557c283', 'Eleccond', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Eleccond', 'Electrical conductivity (EC) measures the ability of soil to conduct an electrical current, which is directly related to the concentration of soluble salts. It is an essential indicator of soil salinity and is used to assess soil''s suitability for crop growth. High EC levels can reduce plant water uptake and affect germination, while low levels indicate low salinity and better soil health. Source: USDA NRCS.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5318570c-5de1-48dc-a2a9-542cdd171227', 'Gyp', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Gyp', 'The gypsum content, expressed as weight, refers to the soil’s calcium sulfate levels. Gypsum improves soil structure, alleviates sodicity, and enhances water infiltration. It is commonly applied to saline-sodic soils for reclamation. Source: FAO Soil Bulletin.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7e5ccc11-a74b-4213-8085-55f86bab78f8', 'Hyd', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Hyd', 'Soluble Hydrocarbonate anions accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('36577047-aca6-4447-8bd0-ce14d879ae14', 'Hydcond', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Hydcond', 'Hydraulic conductivity refers to the rate at which water moves through soil pores under a unit hydraulic gradient. It reflects the soil''s ability to transmit water, influenced by texture, structure, and porosity. Soils with high hydraulic conductivity, like sandy soils, allow rapid water movement, while clayey soils exhibit slower water flow. This property is critical for understanding water infiltration, drainage, and irrigation management. Source: Brady, N.C., &amp; Weil, R.R. (2017). The Nature and Properties of Soils.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3b52fa20-9293-4df3-b8bd-d3cea132150a', 'Hydexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Hydexc', 'Hydrogen ions bound to exchange surfaces in the soil such as clay minerals and organic matter that can be released to the soil solution upon exchange', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a4f6715f-e17b-454b-bc3a-c33f02a9cfe3', 'Irodit', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Irodit', '''Free'' iron content extracted from amorphous compounds (weathering products) as well as crystaline, primary aluminium compounds (parent material) in the soil.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('432d2273-cefa-4eea-8d8d-2d307ba8550a', 'Iroext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Iroext', 'Iron bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('2ed2b773-30ce-42a6-9500-cc42995d7ff1', 'Irooxa', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Irooxa', '''Active'' iron content extracted from amorphous iron compounds that are the products of the weathering of primary soil particles', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('de5070e5-cd98-41f2-a850-b429b00982a2', 'Iropyr', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Iropyr', 'Iron in soil that is organically bound in organo-metal complexes', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('de48684a-be4f-4ddd-9724-6ab84da7a49b', 'Irotot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Irotot', 'Total iron includes all iron forms in the soil, from soluble ferrous iron (Fe²⁺) to insoluble ferric iron (Fe³⁺). Iron is essential for plant chlorophyll synthesis and various enzymatic reactions. Deficiency, often seen in alkaline soils, results in chlorosis, while excessive iron can cause toxicity in acidic soils. Source: Soil Chemistry by Bohn et al.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ecdc594a-192e-44f2-9eac-02e0cf88dcf8', 'Magexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Magexc', 'Magnesium bound to exchange surfaces in the soil such as clay minerals and organic matter that can be released to the soil solution upon exchange', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d59986f5-4772-4b12-a4e8-f428e015d258', 'Magext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Magext', 'Magnesium bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('98fa52a4-995a-48cf-ac74-09ddc111d2fd', 'Magsol', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Magsol', 'Soluble Magnesium cations accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('313d5600-9205-4579-b4cf-527f6be7f18d', 'Magtot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Magtot', 'Total magnesium in soil includes exchangeable, soluble, and mineral-bound forms. Magnesium is essential for chlorophyll synthesis, enzyme activation, and nutrient transport in plants. Its availability is influenced by soil pH and texture. Source: Havlin et al. (2014).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('44e49b00-b8d9-4408-ad98-7c8a144e0baf', 'ManKCl', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-ManKCl', 'KCl extractable manganese measures the readily available manganese fraction in soil. It provides a more accurate assessment of manganese availability to plants than total manganese. This method is commonly used for nutrient management. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('70dd09b3-5faa-4ef6-88d3-a40181fa3e97', 'Mandit', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Mandit', '''Free'' manganese content extracted from amorphous compounds (weathering products) as well as crystaline, primary aluminium compounds (parent material) in the soil.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e9fa59bb-f44e-4ad6-ab16-932030105bcf', 'Manext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Manext', 'Manganese bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('943811b4-5251-42ce-bb3f-063f1af2cf90', 'Manoxa', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Manoxa', '''Active'' manganese content extracted from amorphous manganese compounds that are the products of the weathering of primary soil particles', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('de6b09cf-fdee-4968-9646-69b741f41764', 'Manpyr', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Manpyr', 'Manganese in soil that is organically bound in organo-metal complexes', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('11d03741-4b78-49c1-8b78-38f49f35d2df', 'Mantot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Mantot', 'Total manganese refers to all forms of manganese in the soil, which is critical for photosynthesis, enzyme activation, and nitrogen metabolism in plants. Manganese deficiencies or toxicities are influenced by soil pH, with deficiencies occurring in high-pH soils and toxicities in low-pH, waterlogged soils.  Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('6f8d29bc-ac7c-48db-ac96-d270766030c7', 'Mol', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Mol', 'Molybdenum is a micronutrient essential for plant enzymes involved in nitrogen fixation and nitrate reduction. Deficiency, often observed in acidic soils, can lead to stunted growth and poor nitrogen utilization. Its availability increases with higher pH, making liming a common solution for molybdenum deficiencies. Source: Havlin et al. (2014).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7d7efca5-7d80-4032-9a7d-e3c680939b98', 'Nit2', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Nit2', 'Soluble Nitrite anions accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e0af530e-7908-42c9-b662-bb29a2590787', 'Nit3', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Nit3', 'Soluble Nitrate anions accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a5fa9eab-0305-4d90-9c80-cf33d087529d', 'Nittot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Nittot', 'Total nitrogen encompasses all nitrogen forms in soil, including organic nitrogen in humus and inorganic nitrogen such as ammonium (NH₄⁺) and nitrate (NO₃⁻). Nitrogen is essential for plant growth, being a vital component of amino acids, proteins, and chlorophyll. Total nitrogen is a key indicator of soil fertility and its capacity to sustain long-term crop productivity. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('56225c56-7520-434c-8529-7cc965c0538d', 'Orgmat', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Orgmat', 'Soil organic matter is composed of decomposed plant and animal residues, living soil organisms, and humus. It improves soil structure, water retention, nutrient supply, and microbial activity, making it critical for sustainable agriculture and soil health. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('edace05c-0f38-419a-af05-e580535f40d3', 'Pho', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Pho', 'Soluble Phosphate anions accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('fc99170c-43ce-40c1-b380-f16db3523162', 'Phoext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Phoext', 'Phosphorus bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d71268e6-395c-4c1a-850b-cf907ea333b0', 'Phooxa', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Phooxa', '''Active'' phosphorus content extracted from amorphous phosphorus compounds that are the products of the weathering of primary soil particles', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5d699ce2-35d1-44e7-a2d2-4b3d11d4a00b', 'Phoret', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Phoret', 'Phosphorus retention measures a soil''s capacity to adsorb and hold phosphorus, influenced by soil texture, pH, and mineralogy. While high retention reduces leaching, it may also limit phosphorus availability to plants. Understanding phosphorus retention helps optimize fertilization and minimize environmental impacts. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('53f488d6-161e-42e4-ab01-b69725914a89', 'Photot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Photot', 'Total phosphorus includes all forms of phosphorus in the soil, both organic and inorganic. While only a fraction is plant-available, total phosphorus serves as a long-term reserve for crop nutrition. Adequate phosphorus levels are crucial for energy transfer, photosynthesis, and root development in plants. Source: Soil Chemistry by Bohn et al.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('99f083ac-278e-488b-b9e9-88dcadfbfebf', 'Por', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Por', 'Porosity refers to the percentage of soil volume occupied by pores or voids, which hold air and water. It directly impacts water infiltration, drainage, and root growth. Soils with high porosity are better suited for crop cultivation, as they provide good aeration and water availability. Source: Brady &amp; Weil (2017).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b48bc603-3ba8-45a9-9a5d-ceb7c80d8915', 'Potexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Potexc', 'Potassium bound to exchange surfaces in the soil such as clay minerals and organic matter that can be released to the soil solution upon exchange', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ef63b62a-c995-495e-95bb-993a393a47c8', 'Potext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Potext', 'Potassium bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('bdf2fa99-43da-48e5-8110-e5ca41e0192b', 'Potsol', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Potsol', 'Soluble Potassium cations accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('00681f3b-5f61-4199-b505-4d5be9d96366', 'Pottot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Pottot', 'Total potassium includes all forms of potassium in soil, such as mineral-bound, exchangeable, and water-soluble potassium. It plays a vital role in plant growth by regulating water balance, enzyme activation, and photosynthesis. While only a fraction of total potassium is readily available to plants, it serves as a reserve to replenish exchangeable potassium over time. Adequate potassium levels improve crop yield, quality, and resistance to stress. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('9fee2f39-b188-47d5-8c1d-3f296a00b4e1', 'Selext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Selext', 'Selenium bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e8cf7bb9-9393-4a2b-9fb0-5aaa74cc9eb3', 'Seltot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Seltot', 'Total selenium includes all selenium forms in soil, ranging from organic selenium in humus to inorganic selenium compounds. While trace amounts are essential for animal and human nutrition, excessive selenium can be toxic. Understanding selenium levels is critical for food safety and environmental management. Source: Sparks, D.L. (2003). Environmental Soil Chemistry.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('eaf4ebd9-74d6-4c89-9084-700ea8fbd6ee', 'Siloxa', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Siloxa', '''Active'' silicon content extracted from amorphous silicon compounds that are the products of the weathering of primary soil particles', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('3ef32e4b-a921-4cde-a0ca-b85755299fbc', 'Sodexc', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sodexc', 'Exchangeable sodium percentage (ESP) measures the proportion of sodium ions in the cation exchange complex. High ESP levels (&gt;15%) indicate sodic soils, which are prone to poor structure, reduced permeability, and nutrient imbalances. Management strategies include gypsum application and leaching. Source: USDA NRCS.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('994ab9b9-e756-4ad9-89d5-df71ad748ef4', 'Sodexp', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sodexp', 'Sodium bound to exchange surfaces in the soil such as clay minerals and organic matter that can be released to the soil solution upon exchange', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f06fd980-3a38-465d-8446-336b16b20ad3', 'Sodext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sodext', 'Sodium bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b9492066-9f37-4794-912b-b2f1cffec668', 'Sodsol', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sodsol', 'Soluble Sodium cations accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('01a64a79-b383-4057-9068-c16ce0034f71', 'Sodtot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sodtot', 'Total sodium includes all sodium present in soil, both soluble and bound. Excess sodium can lead to sodicity, which disrupts soil structure, reduces permeability, and impairs plant growth. Monitoring sodium levels is crucial for managing soil salinity in arid and irrigated regions. Source: Bohn, H.L., et al. (2001). Soil Chemistry.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('7ee4d784-3abd-4f52-8f14-13c4f964c7e0', 'Solsal', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Solsal', 'Soluble salts refer to dissolved salts in the soil solution, primarily composed of sodium, calcium, magnesium, chloride, and sulfate ions. Excessive soluble salts cause salinity, which can impair plant water uptake and lead to osmotic stress. EC testing helps monitor salinity levels for effective management. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('849c3d8b-b572-496c-8d2b-f74e3cf6309d', 'Sul', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sul', 'Soluble Sulfate anions accumulated in the soil. A contributor to soil salinisation.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b1077f43-a994-4d15-8abe-f2bd3c4691a7', 'Sulext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sulext', 'Sulfur bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d8629550-4e68-4f9b-b03b-f396871e8d49', 'Sultot', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Sultot', 'Total sulfur in soil includes both organic and inorganic forms, such as sulfates and sulfur in organic matter. Sulfur is essential for protein synthesis and enzyme functions in plants. Deficiency leads to stunted growth and yellowing of leaves. Total sulfur provides insight into the soil''s potential to release plant-available sulfur over time, critical for sustaining crop health. Source: Havlin, J.L., et al. (2014). Soil Fertility and Fertilizers.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('534a2647-122a-46fe-86b6-84f2c927cb2e', 'Zin', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Zin', 'Zinc is a micronutrient essential for plant enzyme systems, protein synthesis, and growth regulation. Deficiency is common in calcareous soils and results in stunted growth and chlorosis. Zinc fertilizers or soil pH adjustments can address deficiencies. Source: Havlin et al. (2014).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('236f8de3-72de-4532-8bb8-bcaa5115b4fb', 'Zinext', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-Zinext', 'Zinc bound to the soil matrix but that can be released into the soil solution (i.e. become bio-available)', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('2422dfa9-82a2-4e73-9f63-630d055dcd43', 'pH', 'http://w3id.org/glosis/model/codelists/physioChemicalPropertyCode-pH', 'Soil pH measures the concentration of hydrogen ions (H⁺) in the soil solution, indicating its acidity or alkalinity on a scale from 1 to 14. Neutral soils have a pH of 7, while values below 7 are acidic and above are alkaline. Soil pH significantly affects nutrient availability, microbial activity, and plant growth. For instance, nutrients like phosphorus are most available in a pH range of 6 to 7. Lime or sulfur applications can adjust soil pH to optimize conditions for crops. Source: USDA Natural Resources Conservation Service (NRCS).', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a34df578-e959-49af-9def-bda0ab31abd6', 'SWD1', 'http://w3id.org/glosis/model/codelists/sandPropertyCode-SWD1', 'Sand water dispersible at 0.1 indicates the sand fraction of soil that can be dispersed into water under a pressure of 0.1. This measure helps assess the ease with which sand particles can separate from aggregates and become suspended in water, impacting soil erosion potential and water retention characteristics. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('838a7c53-1d29-4746-ac09-de007c86ca53', 'SWD2', 'http://w3id.org/glosis/model/codelists/sandPropertyCode-SWD2', 'Sand water dispersible at 0.2 measures the sand fraction that can be dispersed at a 0.2 pressure. This parameter is crucial for evaluating the soil’s risk for erosion, particularly for sandy soils where the potential for particle dispersion can lead to structural degradation. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('67eca92c-6f35-470c-a6c7-a10b0e327f34', 'SWD3', 'http://w3id.org/glosis/model/codelists/sandPropertyCode-SWD3', 'Sand water dispersible at 0.3 refers to the portion of sand particles in the soil that can be dispersed into water under a specific condition, where the dispersion occurs at a 0.3 pressure. This measurement indicates how easily the sand fraction of the soil can break apart and be suspended in water. Dispersible sand is important in evaluating soil structure and its susceptibility to erosion and runoff. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('24a697c4-aac6-4fd1-828a-b3dfd22b8b2b', 'SWD4', 'http://w3id.org/glosis/model/codelists/sandPropertyCode-SWD4', 'Sand water dispersible at 0.4 measures the fraction of sand particles that can be dispersed at a 0.4 pressure. This is useful for understanding how sand interacts with water under varying levels of stress, providing insight into soil stability, especially in sandy soils where dispersion might influence the soil structure and erosion potential. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('291af6a3-db29-4ee4-a078-8378f921d62b', 'SWD5', 'http://w3id.org/glosis/model/codelists/sandPropertyCode-SWD5', 'Sand water dispersible at 0.5 refers to the amount of sand particles that can be dispersed into water when subjected to a pressure of 0.5. This measure is used to assess the potential for soil degradation, particularly in sandy soils where dispersion may lead to erosion or changes in soil structure. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('96fc8e13-2b50-424e-9506-8710556fecbb', 'SWDT', 'http://w3id.org/glosis/model/codelists/sandPropertyCode-SWDT', 'Sand water dispersible total refers to the sum of all sand particles that can be dispersed into water across a range of pressures, usually reflecting the total amount of dispersible sand in the soil. This value is important in understanding the overall erodibility of a soil, as high dispersibility is linked to increased susceptibility to erosion and degradation. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('e1e50f31-f824-4789-af78-99288e5950b3', 'SWDF1', 'http://w3id.org/glosis/model/codelists/siltPropertyCode-SWDF1', 'Silt water dispersible fraction at 0.1 refers to the portion of silt particles that can be dispersed into water when subjected to a 0.1 pressure. This measure helps determine the soil''s erodibility, as silt tends to be more easily dispersed than sand, contributing to the formation of suspended particles in water, which can affect water quality and soil health. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c21091d2-9444-40bd-88bc-efc72f3ebfa8', 'SWDF2', 'http://w3id.org/glosis/model/codelists/siltPropertyCode-SWDF2', 'Silt water dispersible fraction at 0.2 quantifies the amount of silt particles in the soil that can be dispersed at a 0.2 pressure. Dispersible silt can have a significant impact on soil stability and is particularly relevant for understanding how silt behaves under wet conditions, affecting erosion rates and water retention. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('2881fb05-98b1-4c7c-8e4d-5e63085866c7', 'SWDFT', 'http://w3id.org/glosis/model/codelists/siltPropertyCode-SWDFT', 'Silt water dispersible fraction total refers to the total amount of silt particles that can be dispersed into water across different pressures. This total measure indicates the overall dispersibility of silt in a soil, which is important for assessing the soil’s vulnerability to erosion and degradation, especially in soils with a high silt content. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ecca9e14-4864-465a-9724-2fea4fca075b', 'CC', 'http://w3id.org/glosis/model/codelists/clayPropertyCode-CC', 'Clay carbonate refers to clay particles that are associated with or contain carbonate minerals, particularly calcium carbonate (CaCO₃). These carbonates are typically present in soils with higher pH (alkaline soils), and they play a significant role in buffering soil acidity. Clay-carbonate soils are found in regions with semi-arid and arid climates, where evaporation exceeds precipitation. These soils can have distinct properties, including a lower cation exchange capacity compared to non-carbonate soils and an ability to neutralize soil acidity, influencing both soil fertility and plant growth. Source: Brady &amp; Weil (2017), The Nature and Properties of Soils.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ea29e06b-8041-4218-8292-53dbfda596a8', 'CNC', 'http://w3id.org/glosis/model/codelists/clayPropertyCode-CNC', 'Clay non-carbonate refers to the fraction of clay particles in soil that do not contain carbonates. Clay particles are very fine mineral components that contribute to the soil''s texture and are typically smaller than 0.002 mm in diameter. The term non-carbonate implies that these clay particles are not associated with carbonate minerals, such as calcium carbonate (lime), which are commonly found in soils in arid or semi-arid regions. Non-carbonate clay soils are often more acidic, with higher cation exchange capacity, and may require different management practices, especially for nutrient availability and soil pH control. Source: Brady &amp; Weil (2017), The Nature and Properties of Soils.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c6420ef2-ae59-49fb-b5f3-f9f34f9ec472', 'CWT', 'http://w3id.org/glosis/model/codelists/clayPropertyCode-CWT', 'Clay water dispersible refers to the portion of clay particles in soil that can be dispersed into water, forming a suspension when the soil is wetted. This characteristic is significant in assessing soil stability, particularly in the presence of water. Water-dispersible clays can lead to erosion problems, as the particles are more easily detached and transported by water. This term is important in understanding soil erodibility, especially in soils with high clay content that are prone to degradation when subjected to rainfall or irrigation. The dispersibility of clay affects both the physical structure and water-holding capacity of the soil. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f53e6d21-7f11-4b4c-bfce-1e312632c3a3', 'Cl', 'http://w3id.org/glosis/model/codelists/textClayPropertyCode-Cl', 'Very fine mineral particles smaller than 2 µm', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('728a5f08-c29d-4a80-86ea-6c6b31912e10', 'Sa_ISO', 'http://w3id.org/glosis/model/codelists/textSandPropertyCode-Sa_ISO', 'Content of mineral particles with sizes between 0.063-2 mm in soil', null, 'SoilWise');
