INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a46c1b52-cee7-4b0b-9f7e-f9d5fcea5856', 'fSa_ISO', 'http://w3id.org/glosis/model/codelists/textSandPropertyCode-fSa_ISO', 'Content of mineral particles with sizes between 0.063-0.2 mm in soil', null, 'SoilWise');
