INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('06be85b9-e16d-4609-b974-3addc06df264', 'Si_USDA', 'http://w3id.org/glosis/model/codelists/textSiltPropertyCode-Si_USDA', 'Content of mineral particles with sizes between 2-50 µm in soil', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('08f8bd3b-4443-4e9d-b34f-56bd70328e81', 'cSi_ISO', 'http://w3id.org/glosis/model/codelists/textSiltPropertyCode-cSi_ISO', 'Content of mineral particles with sizes between 20-63 µm in soil', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('0ee1970f-c739-4cd3-b46d-da6f7d0694fd', 'cSi_USDA', 'http://w3id.org/glosis/model/codelists/textSiltPropertyCode-cSi_USDA', 'Content of mineral particles with sizes between 20-50 µm in soil', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('09fbf88d-e3ce-48a4-9a23-8e7952d4bd4f', 'fSi_ISO', 'http://w3id.org/glosis/model/codelists/textSiltPropertyCode-fSi_ISO', 'Content of mineral particles with sizes between 2-6.3 µm in soil', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('1f7c5a91-4753-422a-9710-64d5d0790137', 'fSi_USDA', 'http://w3id.org/glosis/model/codelists/textSiltPropertyCode-fSi_USDA', 'Content of mineral particles with sizes between 2-20 µm in soil', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f7830d2f-f26d-408b-9200-2b302c741cde', 'mSi_ISO', 'http://w3id.org/glosis/model/codelists/textSiltPropertyCode-mSi_ISO', 'Content of mineral particles with sizes between 6.3-20 µm in soil', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f3a8965e-9371-48a2-b667-9f6f2f00fe26', 'WRG', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG', 'Gravimetric water retention refers to the amount of water held by the soil measured by weight, often expressed in terms of mass per unit mass of soil. It is a fundamental method for assessing soil moisture content and can be determined at various suction pressures like 33 kPa or 1500 kPa. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('76bf1b2b-436c-4ea1-9913-5fc598099d08', 'WRG10', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG10', 'Gravimetric water retention at 10 kPa measures the water held in the soil at 10 kPa pressure, commonly representing the moisture content that is available to plants under normal growing conditions. This measurement is crucial for assessing the soil’s capacity to retain and supply water to plants. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('6f6b7e16-b2a6-40e4-a930-5281b92abf7f', 'WRG100', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG100', 'Gravimetric water retention at 100 kPa measures the water retained by the soil at this specific pressure, using the gravimetric method. It indicates the moisture available to plants between field capacity and the wilting point, providing a useful measurement for soil water management. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('f155e61d-afb1-4ef9-8b99-1f7817d5554e', 'WRG1500', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG1500', 'Gravimetric water retention at 1500 kPa refers to the mass of water retained by the soil at this pressure, as measured by the gravimetric method (weighing the soil before and after drying). This pressure represents the point at which water is tightly held by the soil and is no longer easily accessible to plants, closely corresponding to the permanent wilting point. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('ea9a2990-2eb8-455b-9415-6bf52f4ecf84', 'WRG200', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG200', 'Gravimetric water retention at 200 kPa is the mass of water retained by the soil at this specific suction pressure. It provides insight into the soil’s ability to retain water that is not easily lost by evaporation, offering a more accurate measurement of water held at pressures significant for plant growth. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b6991e72-9e87-4486-a0db-f43da27d1ac7', 'WRG33', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG33', 'Gravimetric water retention at 33 kPa measures the amount of water retained by the soil at this specific pressure, determined by the mass of water held in the soil when subjected to the 33 kPa suction. It reflects the soil’s capacity to hold water available to plants under conditions of moderate water stress. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b43af117-a718-4741-9ed3-9372de6971a2', 'WRG500', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG500', 'Gravimetric water retention at 500 kPa indicates the amount of water retained in the soil at this pressure. This is closer to the permanent wilting point, with the gravimetric method determining the mass of water held in the soil at this specific tension. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4693fac2-d0da-4058-a8c9-77bfc7e02bc7', 'WRG6', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRG6', 'Gravimetric water retention at 6 kPa measures the soil''s water content at a low suction pressure, typically indicative of the moisture available to plants under less favorable conditions. The gravimetric method involves weighing the soil before and after drying to assess the retained water. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('4fad4a91-9959-423d-b09b-78e6dee08849', 'WRV', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV', 'Volumetric water retention refers to the amount of water retained in the soil, expressed as a volume per unit volume of soil. This measure is crucial for understanding the soil''s ability to retain and supply water to plants, and it is often assessed at different matric potentials, such as 33 kPa or 1500 kPa, depending on the context. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('a8e5f075-0467-44cb-bbab-a979da17f1ee', 'WRV10', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV10', 'Water retention at 10 kPa measures the volumetric water content of the soil at this pressure, which is typically considered within the zone of plant-available water. At 10 kPa, the soil retains water that can be easily accessed by plants for growth and physiological processes. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('701a4cfb-9bca-4202-88f3-27dfa578f58d', 'WRV100', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV100', 'Water retention at 100 kPa measures the volumetric water content in the soil at this pressure. This value is often used to assess the availability of water for plant uptake under normal conditions, as it lies between field capacity and the wilting point for many soils. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('d065a5df-8f3b-4952-9e43-3374aac2208a', 'WRV1500', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV1500', 'Water retention at 1500 kPa (or field capacity) measures the amount of water that a soil can hold at this specific suction pressure. This is a critical indicator of the soil''s ability to retain water against gravity after it has drained. At 1500 kPa, the soil''s moisture content represents the point at which most of the water available for plant use has been drained, and it is typically considered the permanent wilting point. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('5ef4a4c3-b726-40c4-a3f3-3b856b2c1535', 'WRV200', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV200', 'Water retention at 200 kPa refers to the volumetric water content retained by the soil at a 200 kPa pressure. This measurement typically lies between the field capacity and wilting point, giving an indication of the soil’s ability to hold water that plants can access under moderate stress conditions. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('b30570f3-a499-4a43-9a1f-2c7e7e3014c2', 'WRV33', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV33', 'Water retention at 33 kPa represents the volumetric water content in soil at a pressure of 33 kPa, which is often associated with the field capacity of the soil. At this pressure, water is held in the soil that is available for most plant species, providing a balance between water retention and drainage. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('2479640a-f4ad-4a5e-8995-c2ae3f7bc22f', 'WRV500', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV500', 'Water retention at 500 kPa measures the volumetric water content of the soil at a pressure of 500 kPa, which lies between field capacity and permanent wilting point. This pressure is commonly used in assessing soil water retention characteristics for plants that are not able to access water at extremely low pressures. The volumetric water content at 500 kPa indicates the soil''s capacity to hold water that is readily available for plant uptake. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observedproperty (guid, name, definition, description, properties, source) VALUES ('c1a3d6d8-07ff-4b5d-a34f-9dab9ae3bc4a', 'WRV6', 'http://w3id.org/glosis/model/codelists/waterRetentionPropertyCode-WRV6', 'Volumetric water retention at 6 kPa measures the soil’s ability to hold water at a low pressure, typically indicating the moisture content available to plants under conditions of mild water stress. It is important for understanding the soil''s water-holding capacity and potential for plant growth. Source: Soil Science Society of America.', null, 'SoilWise');
INSERT INTO observingprocedure (guid, name, definition, description, properties) VALUES ('740c7433-2822-4ab4-a835-ac65e775a426', 'EffCEC_calcul-b', 'http://w3id.org/glosis/model/procedure/effectiveCecProcedure-EffCEC_calcul-b', 'Sum of exchangeable bases (Ca, Mg, K, Na) without exchangeable acidity (H+Al), see ExchBases and ExchAcids for methods', null);
